"""Validate that report.pdf now begins with a cover page containing the title
'Annual Financial Report' and the current date, followed by the original pages.
Reads only report.pdf; performs pure-stdlib structural verification."""

import os
import re
import sys
from datetime import datetime

INPUT_NAME = "report.pdf"
TITLE = "Annual Financial Report"
EXPECTED_TOTAL = 2  # cover page + the single original page


def find_input():
    candidates = [os.path.join(os.getcwd(), INPUT_NAME)]
    script_dir = os.path.dirname(os.path.abspath(__file__))
    if script_dir != os.getcwd():
        candidates.append(os.path.join(script_dir, INPUT_NAME))
    for path in candidates:
        if os.path.isfile(path):
            return path
    return None


def read_object_at(data, off):
    kw = data.find(b"obj", off)
    eol = data.find(b"\n", kw)
    body_start = eol + 1
    end = data.find(b"endobj", body_start)
    stream_kw = data.find(b"stream", body_start, end)
    if stream_kw != -1:
        es = data.find(b"endstream", stream_kw)
        end = data.find(b"endobj", es)
    return data[body_start:end].rstrip(b"\r\n")


def parse_classic_xref(data, pos):
    entries = {}
    p = pos + len(b"xref")
    while True:
        while p < len(data) and data[p:p + 1] in (b" ", b"\r", b"\n", b"\t"):
            p += 1
        line_end = data.find(b"\n", p)
        if line_end == -1:
            line_end = len(data)
        line = data[p:line_end].strip()
        p = line_end + 1
        if line == b"trailer" or not line:
            break
        parts = line.split()
        if len(parts) != 2:
            break
        start, count = int(parts[0]), int(parts[1])
        for i in range(count):
            entry = data[p:p + 20]
            p += 20
            if len(entry) < 20:
                break
            off = int(entry[0:10])
            gen = int(entry[11:16])
            typ = entry[17:18]
            if typ == b"n" and off > 0:
                entries.setdefault(start + i, (off, gen))
    return entries


def get_ref(obj_text, key):
    m = re.search((rb"/" + key + rb")\s+(\d+)\s+(\d+)\s+R"), obj_text)
    return int(m.group(2)) if m else None


def main():
    input_path = find_input()
    if input_path is None:
        print("FAIL: report.pdf not found", file=sys.stderr)
        return 1
    with open(input_path, "rb") as fh:
        data = fh.read()

    failures = []

    if not data.startswith(b"%PDF"):
        failures.append("missing %PDF header")

    starts = re.findall(rb"startxref\s+(\d+)", data)
    if not starts:
        failures.append("missing startxref")
        print("FAIL: " + "; ".join(failures))
        return 1
    offsets = {}
    pos = int(starts[-1])
    seen = set()
    root_ref = None
    while pos and pos not in seen:
        seen.add(pos)
        if not data[pos:pos + 4] == b"xref":
            failures.append("unexpected xref format at %d" % pos)
            break
        for num, val in parse_classic_xref(data, pos).items():
            offsets.setdefault(num, val)
        tline = data.find(b"trailer", pos)
        tend = data.find(b"startxref", tline)
        trailer = data[tline:tend]
        m = re.search(rb"/Root\s+(\d+)\s+(\d+)\s+R", trailer)
        if m:
            root_ref = int(m.group(1))
        m = re.search(rb"/Prev\s+(\d+)", trailer)
        pos = int(m.group(1)) if m else 0

    if root_ref is None:
        failures.append("no /Root in trailer")
    else:
        catalog = read_object_at(data, offsets[root_ref][0])
        pages_num = get_ref(catalog, b"Pages")
        if pages_num is None:
            failures.append("catalog has no /Pages")
        else:
            pages = read_object_at(data, offsets[pages_num][0])
            m = re.search(rb"/Count\s+(\d+)", pages)
            count = int(m.group(1)) if m else -1
            if count != EXPECTED_TOTAL:
                failures.append("root /Count is %d, expected %d" % (count, EXPECTED_TOTAL))
            kids_m = re.search(rb"/Kids\s*\[([^\]]*)\]", pages)
            kids = kids_m.group(1).split() if kids_m else []
            if len(kids) != 4:  # two refs: "N 0 R N 0 R"
                failures.append("root /Kids has %d tokens, expected 4" % len(kids))
            else:
                cover_num = int(kids[0])
                orig_pages_num = int(kids[2])
                cover = read_object_at(data, offsets[cover_num][0])
                if b"/Type /Page" not in cover:
                    failures.append("first kid is not a page object")
                m = re.search(rb"/MediaBox\s*\[\s*0\s+0\s+612\s+792\s*\]", cover)
                if not m:
                    failures.append("cover page MediaBox is not 612x792")
                contents_ref = re.search(rb"/Contents\s+(\d+)\s+(\d+)\s+R", cover)
                if contents_ref:
                    stream_obj = read_object_at(
                        data, offsets[int(contents_ref.group(1))][0])
                    sm = re.search(rb"stream\r?\n(.*?)\r?\nendstream", stream_obj, re.S)
                    stream = sm.group(1) if sm else b""
                    if TITLE.encode("latin-1") not in stream:
                        failures.append("cover stream missing title")
                    if datetime.now().strftime("%B %d, %Y").encode("latin-1") not in stream:
                        failures.append("cover stream missing current date")
                else:
                    failures.append("cover page has no /Contents")
                orig_pages = read_object_at(data, offsets[orig_pages_num][0])
                m = re.search(rb"/Count\s+(\d+)", orig_pages)
                if not m or int(m.group(1)) != EXPECTED_TOTAL - 1:
                    failures.append("original /Pages count is not %d" % (EXPECTED_TOTAL - 1))

    if failures:
        print("VALIDATION FAILED:")
        for f in failures:
            print("  - " + f)
        return 1

    print("VALIDATION OK")
    print("File: %s" % input_path)
    print("Root /Pages count: %d" % EXPECTED_TOTAL)
    print("First page (cover): title=%r, date=%s, MediaBox=612x792"
          % (TITLE, datetime.now().strftime("%B %d, %Y")))
    print("Second page: original report content preserved (count %d)"
          % (EXPECTED_TOTAL - 1))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

